def solve(values):
    class Node:
        def __init__(self, value, next=None): self.value, self.next = value, next
    head = None
    for value in reversed(values): head = Node(value,head)
    previous = None
    while head:
        following = head.next
        head.next = previous
        previous, head = head, following
    answer = []
    while previous:
        answer.append(previous.value); previous = previous.next
    return answer
